from collections import Counter
import statistics
from tenx.engine import _run_decision_core
from empirical.backbone import run_empirical_reference
SEEDS=[4,12,20,32,40,52,64]
def run_campaign():
    runs=[_run_decision_core(s) for s in SEEDS]; names=[r['decision']['name'] for r in runs]; modal,n=Counter(names).most_common(1)[0]; margins=[r['decision']['safety_margin'] for r in runs]; guards=[r['decision']['guard_score'] for r in runs]; acc=[r['model_validation']['value'] for r in runs]; emp=run_empirical_reference(); mm=min(margins); state='CLINICIAN_PROGRESSION_REVIEW' if mm>=.2 and min(acc)>=.8 else 'HOLD_PROGRESSION'
    return {'campaign':'Rehabilitation Episode Review Campaign','campaign_identity':'safety-margin volatility + progression stability frontier','scenario_count':len(runs),'scenario_seeds':SEEDS,'state':state,'modal_action':modal,'action_share':round(n/len(runs),4),'minimum_safety_margin':round(mm,5),'mean_safety_margin':round(statistics.mean(margins),5),'safety_margin_stdev':round(statistics.pstdev(margins),5),'mean_guard_score':round(statistics.mean(guards),5),'minimum_hmm_accuracy':round(min(acc),5),'scenario_matrix':[{'seed':s,'action':r['decision']['name'],'gain':r['decision']['gain'],'safety_margin':r['decision']['safety_margin'],'guard_score':r['decision']['guard_score'],'hmm_accuracy':r['model_validation']['value']} for s,r in zip(SEEDS,runs)],'ai_synthesis':{'why':f'{modal} selected in {n}/{len(runs)} episode realizations; minimum modeled safety margin={mm:.3f}.','challenge':'Maximum nominal functional gain is rejected whenever it breaches the modeled safety envelope.','recommended_operator_action':'Review the guarded action and APACE/twin forecast before any progression.','abstention_conditions':['narrow safety margin','poor state-estimation confidence','sensor evidence unreliable','clinical review unavailable']},'action_queue':['review movement/state evidence','inspect HMM confidence and asymmetry','review MOTION-GUARD action','challenge with APACE/digital twin','clinician records progress or HOLD'],'human_authority':'CLINICIAN_REVIEW','autonomous_execution':False,'evidence_boundary':'Engineering decision support only; no clinical efficacy claim.','empirical_provenance':{'mode':emp.get('data_mode'),'promotion':emp.get('empirical_promotion')}}
